<?php
require __DIR__.'/../includes/bootstrap.php'; permit('dashboard'); $section='dashboard'; $title='ภาพรวมการปฏิบัติงาน';
[$scope,$args]=scope();
$total=(int)scalar("SELECT COUNT(*) FROM employees e WHERE e.status='active'".$scope,$args);
$checked=(int)scalar("SELECT COUNT(DISTINCT a.user_id) FROM attendance_logs a JOIN employees e ON e.employee_id=a.user_id WHERE e.status='active' AND a.check_type='เข้างาน' AND a.check_datetime>=CURDATE() AND a.check_datetime<DATE_ADD(CURDATE(),INTERVAL 1 DAY)".$scope,$args);
$late=(int)scalar("SELECT COUNT(DISTINCT a.user_id) FROM attendance_logs a JOIN employees e ON e.employee_id=a.user_id WHERE a.is_late=1 AND a.check_datetime>=CURDATE() AND a.check_datetime<DATE_ADD(CURDATE(),INTERVAL 1 DAY)".$scope,$args);
$pending=(int)scalar("SELECT COUNT(*) FROM offsite_work_requests o JOIN employees e ON e.employee_id=o.employee_id WHERE o.approval_status='รออนุมัติ'".$scope,$args);
$pending+=(int)scalar("SELECT COUNT(*) FROM attendance_logs a JOIN employees e ON e.employee_id=a.user_id WHERE a.approval_status='รออนุมัติ'".$scope,$args);
$cards=[['จำนวนพนักงาน',$total,'people'],['เข้างานวันนี้',$checked,'box-arrow-in-right'],['มาสายวันนี้',$late,'alarm'],['ยังไม่ลงเวลา',max(0,$total-$checked),'clock'],['คำขอรออนุมัติ',$pending,'clipboard-check']];
if(allowed('biometrics'))$cards[]=['ใบหน้ารออนุมัติ',scalar("SELECT COUNT(*) FROM face_biometrics WHERE approval_status='pending' AND status='active'"),'person-bounding-box'];
$recent=q('SELECT a.attendance_id,a.check_datetime,a.check_type,a.zone_status,a.is_late,e.full_name FROM attendance_logs a JOIN employees e ON e.employee_id=a.user_id WHERE 1=1'.$scope.' ORDER BY a.check_datetime DESC LIMIT 10',$args)->fetchAll();
require __DIR__.'/../includes/header.php'; ?>
<p class="text-secondary mb-4">ข้อมูล<?=current_user()['role']==='supervisor'?'เฉพาะแผนกที่คุณดูแล':'ภาพรวมองค์กร'?> • จำนวนผู้เข้างานนับพนักงานไม่ซ้ำรายวัน</p><div class="row g-3 mb-4"><?php foreach($cards as [$label,$value,$icon]):?><div class="col-sm-6 col-xl-4"><div class="card h-100"><div class="card-body"><div class="d-flex justify-content-between align-items-center"><span class="metric-label"><?=e($label)?></span><span class="metric-icon"><i class="bi bi-<?=e($icon)?>"></i></span></div><div class="metric-value"><?=e($value)?></div></div></div></div><?php endforeach;?></div>
<div class="card mb-4"><div class="card-body"><h2 class="h6">สรุปวันนี้</h2><div class="progress my-3" role="progressbar" aria-label="สัดส่วนพนักงานเข้างาน" aria-valuenow="<?=$total?round($checked/$total*100):0?>" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar" style="width:<?=$total?round($checked/$total*100):0?>%"></div></div><span class="text-secondary">เข้างานแล้ว <?=e($checked)?> จาก <?=e($total)?> คน · จำนวนยังไม่ลงเวลาไม่ได้หักวันหยุดหรือการลา</span></div></div>
<div class="card"><div class="card-header d-flex justify-content-between">กิจกรรมลงเวลาล่าสุด<a href="<?=e(url('attendance/'))?>">ดูทั้งหมด →</a></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>พนักงาน</th><th>วัน / เวลา</th><th>ประเภท</th><th>สถานะพื้นที่</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><a href="<?=e(url('attendance/?id='.$r['attendance_id']))?>"><?=e($r['full_name'])?></a></td><td><?=e($r['check_datetime'])?></td><td><?=e($r['check_type'])?> <?=$r['is_late']?badge('มาสาย'):''?></td><td><?=badge($r['zone_status'])?></td></tr><?php endforeach;?></tbody></table><?php if(!$recent):?><div class="empty">ยังไม่มีข้อมูลการลงเวลา</div><?php endif;?></div></div>
<?php require __DIR__.'/../includes/footer.php'; ?>
